import { t as Application } from "../application-TLzZVFOE.js";
//#region factories/app.ts
/**
* App factory is used to generate application class instances for
* testing
*/
var AppFactory = class {
	#parameters = {};
	/**
	* Merge parameters accepted by the AppFactory
	*/
	merge(params) {
		Object.assign(this.#parameters, params);
		return this;
	}
	/**
	* Create application class instance
	*/
	create(appRoot, importer) {
		return new Application(appRoot, Object.assign({ importer }, { environment: "web" }, this.#parameters));
	}
};
//#endregion
export { AppFactory };
